const size_t theme_count = sizeof(themes) / sizeof(themes[0]);

const Theme *theme_by_name(const char *name)
{
    if (!name || !*name) return &themes[0];
    for (size_t i = 0; i < theme_count; i++)
        if (strcasecmp(name, themes[i].name) == 0) return &themes[i];
    return NULL;
}
